// v32: Labs v4 — 25 more smart insights (statistical or rule-based; NO language model) + 85 tools.
// All computed on-device from the same real boards (official / AeroDataBox / live ADS-B), METAR and Skyline's airport DB.
import { useEffect, useState, type ReactNode } from "react";
import { api } from "./lib";
import { delayMin } from "./v25";
import { useAB, useApt, G, Shell, Note, Stat, Bar, Cols, mean, median, isCx, alName, tone, oth, hm, hourIn, AirportPicker } from "./v28";
import { FL, GR, tT, ms, hav, brg, byT, Row, useInfo, card, up, T3 as T } from "./v29";

const dl = (f: any, dir: string) => delayMin(f, dir);
const S = (f: any, dir: string) => (dir === "dep" ? f.dep : f.arr) || {};
const hr = (f: any, dir: string, d: any) => hourIn(S(f, dir).scheduled || tT(f, dir), d.tz);
const km = (f: any, dir: string, d: any) => hav(d.airport, oth(f, dir));
const Ds = (fs: any[], dir: string) => fs.map(f => dl(f, dir)).filter((x: any) => x != null) as number[];
const avg = (fs: any[], dir: string) => { const a = Ds(fs, dir); return a.length ? mean(a) : NaN; };
const pct = (a: number, b: number) => b ? Math.round(100 * a / b) : 0;
const m1 = (v: number) => (v > 0 ? "+" : "") + Math.round(v) + "′";
const p0 = (v: number) => Math.round(v) + "%";
const kmF = (v: number) => Math.round(v).toLocaleString() + " km";
const cont = (p: any) => String(p?.tz || "").split("/")[0] || "";
const sd = (a: number[]) => { const m = mean(a); return Math.sqrt(mean(a.map(x => (x - m) ** 2))); };
const q = (a: number[], p: number) => { const s = [...a].sort((x, y) => x - y); return s.length ? s[Math.min(s.length - 1, Math.floor(p * s.length))] : 0; };
const inH = (f: any, dir: string, d: any, a: number, b: number) => { const h = hr(f, dir, d); return a <= b ? h >= a && h < b : h >= a || h < b; };
const tzd = (a: string, b: string) => { const o = (tz: string) => { try { const m = new Date().toLocaleString("en-US", { timeZone: tz, timeZoneName: "shortOffset" }).match(/GMT([+-]\d+)(?::(\d+))?/); return m ? +m[1] + (m[2] ? Math.sign(+m[1]) * +m[2] / 60 : 0) : 0; } catch { return 0; } }; return o(b) - o(a); };
const CAP = new Set("LHR LGW STN LTN CDG ORY AMS BRU FRA BER MAD BCN LIS DUB VIE ZRH GVA CPH ARN OSL HEL WAW PRG BUD ATH FCO CIA IST SAW OTP SOF BEG ZAG LJU BTS VNO RIX TLL KEF LUX MLA LCA TIA SKP TGD SJJ KIV KBP TBS EVN GYD CMN RAK TUN ALG CAI AMM BEY TLV DXB AUH DOH BAH KWI MCT RUH JED DEL BOM ISB KHI DAC KTM CMB BKK SIN KUL CGK MNL HAN SGN PEK PKX PVG HKG ICN NRT HND TPE SYD CBR AKL WLG YYZ YOW IAD DCA JFK MEX BOG LIM SCL EZE GRU BSB NBO ADD JNB CPT LOS ACC DSS".split(" "));
const capOK = (p: any) => !!p && ["LHR","LGW","STN","LTN","CDG","ORY","AMS","BRU","BER","MAD","LIS","DUB","VIE","CPH","ARN","OSL","HEL","WAW","PRG","BUD","ATH","FCO","CIA","IST","OTP","SOF","BEG","ZAG","LJU","BTS","VNO","RIX","TLL","KEF","LUX","MLA","LCA","TIA","SKP","TGD","SJJ","KIV","KBP","TBS","EVN","GYD","CMN","TUN","ALG","CAI","AMM","BEY","TLV","AUH","DOH","BAH","KWI","MCT","RUH","DEL","ISB","DAC","KTM","BKK","SIN","KUL","CGK","MNL","HAN","PEK","PKX","SEL","ICN","NRT","HND","TPE","CBR","WLG","YOW","IAD","DCA","MEX","BOG","LIM","SCL","EZE","BSB","NBO","ADD","ACC","DSS"].includes(p.iata) && CAP.has(p.iata);

// generic "compute and show" card
function Ag({ apt, need = 1, dir: d0, fixed, calc }: any) { const s = useAB(apt, d0 || "dep"); const sh = fixed ? { ...s, sd: undefined } : s; return <Shell {...sh}><G b={s.b} need={need}>{d => calc(d, s.dir, Date.now())}</G></Shell>; }
const V = ({ t, b, s }: { t: string; b: string; s: ReactNode }) => <div className={"l2-verdict " + t}><b>{b}</b><small>{s}</small></div>;
const Rk = ({ R, fmt }: { R: [string, number, number?][]; fmt?: (v: number) => string }) => { const mx = Math.max(1, ...R.map(r => Math.abs(r[1]))); return <>{R.map(([k, v, n], i) => <div key={k} className="lab-row"><span className="l2-rank">{i + 1}</span><span className="grow">{k}{n != null && <small className="faint"> {n} flt</small>}</span><Bar v={Math.abs(v)} max={mx} tone={v >= 30 ? "bad" : v >= 15 ? "warn" : ""} /><b>{fmt ? fmt(v) : v}</b></div>)}{!R.length && <Note>Not enough data on this board yet.</Note>}</>; };
const grp = (fs: any[], k: (f: any) => string) => { const M: Record<string, any[]> = {}; fs.forEach(f => { const x = k(f); if (x) (M[x] ||= []).push(f); }); return M; };

// ======================= 25 smart (statistical / rule-based) =======================
function LateOdds({ apt }: any) { return <Ag apt={apt} need={3} calc={(d: any, dir: string) => { const A = d.flights.filter((f: any) => dl(f, dir) != null); if (A.length < 5) return <Note>Need 5+ flights with times ({A.length}).</Note>; const H = grp(A, f => String(hr(f, dir, d)).padStart(2, "0"));
  return <><Cols data={Object.keys(H).sort().map(h => ({ k: h, v: pct(H[h].filter((f: any) => dl(f, dir)! >= 15).length, H[h].length), t: "warn" }))} fmt={p0} /><Note>Empirical chance a flight is 15+ min late, by scheduled hour (share of today's flights with times in that hour). Small hours can be noisy.</Note></>; }} />; }
function BayesOT({ apt }: any) { return <Ag apt={apt} need={3} calc={(d: any, dir: string) => { const A = d.flights.filter((f: any) => dl(f, dir) != null); if (A.length < 5) return <Note>Need 5+ timed flights.</Note>; const p = A.filter((f: any) => dl(f, dir)! < 15).length / A.length, k = 5; const M = grp(A, alName);
  const R = Object.entries(M).map(([a, fs]) => [a, Math.round(100 * (fs.filter((f: any) => dl(f, dir)! < 15).length + k * p) / (fs.length + k)), fs.length] as [string, number, number]).sort((a, b) => b[1] - a[1]);
  return <><Rk R={R} fmt={p0} /><Note>Bayesian (beta-prior) on-time rate: each airline is shrunk toward the airport's {Math.round(p * 100)}% by 5 pseudo-flights, so one lucky flight doesn't top the table.</Note></>; }} />; }
function BayesCx({ apt }: any) { return <Ag apt={apt} need={3} calc={(d: any) => { const F = d.flights, p = F.filter(isCx).length / F.length, k = 10; const R = Object.entries(grp(F, alName)).map(([a, fs]) => [a, Math.round(1000 * (fs.filter(isCx).length + k * p) / (fs.length + k)) / 10, fs.length] as [string, number, number]).sort((a, b) => b[1] - a[1]).slice(0, 15);
  return <><Rk R={R} fmt={v => v + "%"} /><Note>Smoothed cancellation risk per airline (beta prior, 10 pseudo-flights at the airport rate of {(p * 100).toFixed(1)}%). Statistical estimate.</Note></>; }} />; }
function ZOut({ apt, open }: any) { return <Ag apt={apt} need={3} calc={(d: any, dir: string) => { const A = d.flights.filter((f: any) => dl(f, dir) != null); const M = grp(A, alName); const L = A.filter((f: any) => { const a = Ds(M[alName(f)], dir); if (a.length < 4) return false; const s = sd(a); return s > 0 && (dl(f, dir)! - mean(a)) / s >= 2; });
  return <>{L.map((f: any) => <Row key={f.id} f={f} dir={dir} tz={d.tz} open={open} />)}{!L.length && <Note>No flight is 2+ standard deviations later than its airline's average today.</Note>}<Note>Z-score outliers: late compared with the same airline's other flights today (airlines with 4+ timed flights).</Note></>; }} />; }
function Slope({ apt }: any) { return <Ag apt={apt} need={5} calc={(d: any, dir: string) => { const P = d.flights.map((f: any) => [hr(f, dir, d), dl(f, dir)]).filter((p: any) => p[1] != null); if (P.length < 6) return <Note>Need 6+ timed flights.</Note>; const xs = P.map((p: any) => p[0]), ys = P.map((p: any) => p[1]); const mx = mean(xs), my = mean(ys); const b = xs.reduce((a: number, x: number, i: number) => a + (x - mx) * (ys[i] - my), 0) / (xs.reduce((a: number, x: number) => a + (x - mx) ** 2, 0) || 1);
  return <><V t={b > 1 ? "bad" : b < -1 ? "good" : "warn"} b={`${b > 0 ? "+" : ""}${b.toFixed(1)} min per hour of day`} s={b > 1 ? "Later flights run later — knock-on delays build through the day." : b < -1 ? "Later flights run better than early ones today." : "No clear build-up through the day."} /><Note>Least-squares line through {P.length} flights' delay vs scheduled hour.</Note></>; }} />; }
function Ewma({ apt }: any) { return <Ag apt={apt} need={5} calc={(d: any, dir: string, now: number) => { const P = d.flights.filter((f: any) => S(f, dir).actual && dl(f, dir) != null).sort((a: any, b: any) => ms(S(a, dir).actual) - ms(S(b, dir).actual)); if (P.length < 4) return <Note>Need 4+ completed flights.</Note>; let e = dl(P[0], dir)!; P.forEach((f: any) => { e = 0.3 * dl(f, dir)! + 0.7 * e; });
  return <><V t={tone(e)} b={`Next hour ≈ ${m1(e)}`} s={`Exponentially weighted average of ${P.length} completed flights (α = 0.3, recent ones count most).`} /><div className="lab-stats"><Stat l="Plain average" v={m1(mean(Ds(P, dir)))} /><Stat l="Last 3" v={m1(mean(Ds(P.slice(-3), dir)))} /></div><Note>Estimate for flights in the next hour; not a guarantee. Updated {hm(new Date(now).toISOString(), d.tz)}.</Note></>; }} />; }
function Pctl({ apt }: any) { return <Ag apt={apt} need={3} calc={(d: any, dir: string) => { const a = Ds(d.flights, dir); if (a.length < 5) return <Note>Need 5+ timed flights.</Note>; return <><div className="lab-stats"><Stat l="P50" v={m1(q(a, .5))} /><Stat l="P75" v={m1(q(a, .75))} /><Stat l="P90" v={m1(q(a, .9))} tone="warn" /><Stat l="Worst" v={m1(Math.max(...a))} tone="bad" /></div><Note>Plan with P75–P90: 9 in 10 flights today were no later than the P90 figure ({a.length} flights).</Note></>; }} />; }
function K3({ apt }: any) { return <Ag apt={apt} need={5} calc={(d: any, dir: string) => { const a = Ds(d.flights, dir); if (a.length < 6) return <Note>Need 6+ timed flights.</Note>; let c = [q(a, .1), q(a, .5), q(a, .9)]; for (let it = 0; it < 20; it++) { const g: number[][] = [[], [], []]; a.forEach(x => { let j = 0; c.forEach((y, i) => { if (Math.abs(x - y) < Math.abs(x - c[j])) j = i; }); g[j].push(x); }); c = c.map((y, i) => g[i].length ? mean(g[i]) : y); }
  const g = [0, 0, 0]; a.forEach(x => { let j = 0; c.forEach((y, i) => { if (Math.abs(x - y) < Math.abs(x - c[j])) j = i; }); g[j]++; });
  return <>{c.map((y, i) => <div key={i} className="lab-row"><span className="grow">{["Fast group", "Typical group", "Slow group"][i]}<small className="faint"> centre {m1(y)}</small></span><Bar v={g[i]} max={a.length} tone={tone(y)} /><b>{g[i]}</b></div>)}<Note>1-D k-means (k = 3) on today's delays — shows whether delays are spread out or split into distinct groups.</Note></>; }} />; }
function Corr({ apt }: any) { return <Ag apt={apt} need={5} calc={(d: any, dir: string) => { const P = d.flights.map((f: any) => [km(f, dir, d), dl(f, dir)]).filter((p: any) => isFinite(p[0]) && p[1] != null); if (P.length < 6) return <Note>Need 6+ flights with distance and times.</Note>; const xs = P.map((p: any) => p[0]), ys = P.map((p: any) => p[1]); const r = xs.reduce((a: number, x: number, i: number) => a + (x - mean(xs)) * (ys[i] - mean(ys)), 0) / (xs.length * (sd(xs) * sd(ys) || 1));
  return <><V t={Math.abs(r) > .4 ? "warn" : "good"} b={`r = ${r.toFixed(2)}`} s={Math.abs(r) < .2 ? "Distance has almost nothing to do with delay today." : r > 0 ? "Longer flights tend to be later today." : "Shorter flights tend to be later today."} /><Note>Pearson correlation of distance vs delay, {P.length} flights.</Note></>; }} />; }
function Contagion({ apt, open }: any) { return <Ag apt={apt} calc={(d: any, dir: string, now: number) => { const bad = new Set(d.flights.filter((f: any) => !up(f, dir, now) && (dl(f, dir) ?? 0) >= 20).map((f: any) => oth(f, dir)?.iata)); const L = d.flights.filter((f: any) => up(f, dir, now) && bad.has(oth(f, dir)?.iata)).sort(byT);
  return <>{L.map((f: any) => <Row key={f.id} f={f} dir={dir} tz={d.tz} open={open} />)}{!L.length && <Note>No upcoming flight shares a route with an earlier 20+ min delay.</Note>}<Note>Rule: an earlier flight on the same route ran 20+ min late, so this one may be affected too (e.g. weather or slot limits at the other end).</Note></>; }} />; }
function Streak({ apt, open }: any) { return <Ag apt={apt} calc={(d: any, dir: string, now: number) => { const M = grp(d.flights.filter((f: any) => S(f, dir).actual && dl(f, dir) != null).sort(byT), alName); const hot = new Set(Object.entries(M).filter(([, fs]) => fs.length >= 3 && fs.slice(-3).every((f: any) => dl(f, dir)! >= 15)).map(e => e[0])); const L = d.flights.filter((f: any) => up(f, dir, now) && hot.has(alName(f))).sort(byT);
  return <>{[...hot].length ? <V t="warn" b={[...hot].join(", ")} s="last 3 completed flights all 15+ min late" /> : <V t="good" b="No late streaks" s="No airline has 3 late flights in a row" />}{L.slice(0, 20).map((f: any) => <Row key={f.id} f={f} dir={dir} tz={d.tz} open={open} />)}<Note>Rule-based: upcoming flights from an airline on a late streak.</Note></>; }} />; }
function CxRoute({ apt, open }: any) { return <Ag apt={apt} calc={(d: any, dir: string, now: number) => { const C = new Set(d.flights.filter(isCx).map((f: any) => oth(f, dir)?.iata)); const L = d.flights.filter((f: any) => up(f, dir, now) && C.has(oth(f, dir)?.iata)).sort(byT);
  return <>{L.map((f: any) => <Row key={f.id} f={f} dir={dir} tz={d.tz} open={open} />)}{!L.length && <Note>No upcoming flight is on a route that already had a cancellation today.</Note>}<Note>Rule: same route already had a cancellation today — have a backup plan.</Note></>; }} />; }
function GateHold({ apt, open }: any) { return <FL apt={apt} open={open} dir="dep" fixed filt={(f: any, _d: string, n: number) => !isCx(f) && !f.dep?.actual && ms(f.dep?.scheduled) < n - 5 * 6e4 && ms(f.dep?.scheduled) > n - 3 * 36e5} sort={byT} empty="No departure is past its scheduled time without an actual off-block time." note="Rule-based: past scheduled departure but not reported as departed — likely delayed even if the board hasn't updated." />; }
function EarlyOdds({ apt }: any) { return <Ag apt={apt} dir="arr" fixed need={3} calc={(d: any) => { const R = Object.entries(grp(d.flights.filter((f: any) => dl(f, "arr") != null), alName)).filter(([, fs]) => fs.length >= 2).map(([a, fs]) => [a, pct(fs.filter((f: any) => dl(f, "arr")! <= -5).length, fs.length), fs.length] as [string, number, number]).sort((a, b) => b[1] - a[1]);
  return <><Rk R={R} fmt={p0} /><Note>Share of each airline's arrivals landing 5+ min early today (airlines with 2+ timed arrivals).</Note></>; }} />; }
function WxCause({ apt: a0 }: any) { const s = useAB(a0); const [w, sw] = useState<any>(undefined); useEffect(() => { sw(undefined); api(`/wx/${s.apt}`).then(sw).catch(() => sw(null)); }, [s.apt]); return <Shell {...s}><G b={s.b}>{d => { const m = w?.metar?.[0]; const a = Ds(d.flights, s.dir); const av = a.length ? mean(a) : 0; if (w === undefined) return <Note>Loading weather…</Note>;
  const bad = m && (["IFR", "LIFR"].includes(m.fltCat) || (m.wgst ?? 0) >= 30 || (m.wspd ?? 0) >= 25 || /TS|SN|FG|FZ/.test(m.wxString || "")); const v = !m ? ["warn", "No METAR"] : av >= 15 && bad ? ["bad", "Weather likely contributing"] : av >= 15 ? ["warn", "Delays, but weather looks fine"] : bad ? ["warn", "Rough weather, few delays so far"] : ["good", "Weather not a factor"];
  return <><V t={v[0]} b={v[1]} s={`Average delay ${m1(av)} · ${m ? `${m.fltCat || "?"}, wind ${m.wspd ?? "?"} kt${m.wgst ? " G" + m.wgst : ""}${m.wxString ? ", " + m.wxString : ""}` : "no weather report"}`} /><Note>Rule-based: low cloud / poor visibility (IFR), strong or gusty wind, storms, snow or fog, combined with today's delays. It can't see ATC strikes or crew problems.</Note></>; }}</G></Shell>; }
function Pairs({ apt }: any) { return <Ag apt={apt} need={3} calc={(d: any, dir: string) => { const R = Object.entries(grp(d.flights.filter((f: any) => dl(f, dir) != null), f => `${alName(f)} · ${oth(f, dir)?.iata || "?"}`)).filter(([, fs]) => fs.length >= 2).map(([k, fs]) => [k, Math.round(avg(fs, dir)), fs.length] as [string, number, number]).sort((a, b) => b[1] - a[1]).slice(0, 15);
  return <><Rk R={R} fmt={m1} /><Note>Average delay for each airline + route with 2+ timed flights today.</Note></>; }} />; }
function AlFore({ apt }: any) { return <Ag apt={apt} calc={(d: any, dir: string, now: number) => { const R = Object.entries(grp(d.flights.filter((f: any) => f.pred && up(f, dir, now)), alName)).map(([k, fs]) => [k, Math.round(mean(fs.map((f: any) => f.pred.d))), fs.length] as [string, number, number]).sort((a, b) => b[1] - a[1]);
  return <><Rk R={R} fmt={m1} /><Note>Skyline's statistical forecast averaged per airline for flights still to go. Forecasts need a scheduled feed for this airport.</Note></>; }} />; }
function RtFore({ apt }: any) { return <Ag apt={apt} calc={(d: any, dir: string, now: number) => { const R = Object.entries(grp(d.flights.filter((f: any) => f.pred && up(f, dir, now)), f => oth(f, dir)?.city || oth(f, dir)?.iata)).map(([k, fs]) => [k, Math.round(mean(fs.map((f: any) => f.pred.d))), fs.length] as [string, number, number]).sort((a, b) => b[1] - a[1]).slice(0, 15);
  return <><Rk R={R} fmt={m1} /><Note>Average forecast delay per place, flights still to go.</Note></>; }} />; }
function Disagree({ apt, open }: any) { return <FL apt={apt} open={open} filt={(f: any, dir: string, n: number) => f.pred && up(f, dir, n) && dl(f, dir) != null && Math.abs(f.pred.d - dl(f, dir)!) >= 15} right={(f: any, dir: string) => <b className="warn-t">{m1(f.pred.d)} vs {m1(dl(f, dir)!)}</b>} empty="Skyline's forecast and the airline's estimate agree (within 15 min) for every upcoming flight." note="Forecast (left) vs the board's current estimate (right). Big gaps mean one of them is about to change." />; }
function HiConfLate({ apt, open }: any) { return <FL apt={apt} open={open} filt={(f: any, dir: string, n: number) => f.pred && up(f, dir, n) && f.pred.d >= 15 && /high/i.test(f.pred.c || "")} right={(f: any) => <b className="bad-t">{m1(f.pred.d)}</b>} empty="No high-confidence late forecast right now." note="Only forecasts marked high confidence and 15+ min late." />; }
function PeakFore({ apt }: any) { return <Ag apt={apt} calc={(d: any, dir: string, now: number) => { const U = d.flights.filter((f: any) => up(f, dir, now)); if (!U.length) return <Note>No flights left today.</Note>; const H = grp(U, f => String(hr(f, dir, d)).padStart(2, "0")); const ks = Object.keys(H).sort(); const best = ks.reduce((a, b) => H[b].length > H[a].length ? b : a);
  return <><V t="warn" b={`Busiest still to come: ${best}:00`} s={`${H[best].length} flights${H[best].some((f: any) => f.pred) ? ` · forecast avg ${m1(mean(H[best].filter((f: any) => f.pred).map((f: any) => f.pred.d)))}` : ""}`} /><Cols data={ks.map(k => ({ k, v: H[k].length }))} /><Note>From the remaining schedule; queues usually build 1–2 h before a departure peak.</Note></>; }} />; }
function LostMin({ apt }: any) { return <Ag apt={apt} calc={(d: any, dir: string) => { const a = Ds(d.flights, dir).filter(x => x > 0); const tot = a.reduce((x, y) => x + y, 0);
  return <><div className="lab-stats"><Stat l="Delay minutes" v={Math.round(tot).toLocaleString()} tone="warn" /><Stat l="Late flights" v={a.length} /><Stat l="Pax-hours (est.)" v={Math.round(tot * 150 / 60).toLocaleString()} /></div><Note>Passenger-hours assume ~150 passengers per flight — an estimate, not a real head-count.</Note></>; }} />; }
function Anom({ apt }: any) { return <Ag apt={apt} need={3} calc={(d: any, dir: string) => { const C = Array(24).fill(0); d.flights.forEach((f: any) => C[hr(f, dir, d)]++); const nz = C.filter(x => x); const m = mean(nz), s = sd(nz);
  return <><Cols data={C.map((v, i) => ({ k: String(i), v, t: v > m + s ? "bad" : "" }))} /><Note>Red hours are busier than average + 1 standard deviation ({m.toFixed(1)} ± {s.toFixed(1)} flights/h).</Note></>; }} />; }
function Health2({ apt }: any) { return <Ag apt={apt} need={3} calc={(d: any, dir: string) => { const a = Ds(d.flights, dir); const ot = a.length ? a.filter(x => x < 15).length / a.length : 1; const cx = d.flights.filter(isCx).length / d.flights.length; const sc = Math.max(0, Math.round(100 * ot - 300 * cx - Math.max(0, q(a, .9) - 30) / 3)); const g = sc >= 85 ? "A" : sc >= 70 ? "B" : sc >= 55 ? "C" : sc >= 40 ? "D" : "F";
  return <><V t={sc >= 70 ? "good" : sc >= 50 ? "warn" : "bad"} b={`Grade ${g} · ${sc}/100`} s={`on-time ${Math.round(ot * 100)}% · cancelled ${(cx * 100).toFixed(1)}% · P90 ${m1(q(a, .9))}`} /><Note>Rule-based grade: on-time share, minus penalties for cancellations and a long tail of big delays.</Note></>; }} />; }
function MyFore({ apt: a0 }: any) { const [n, sn] = useState(""); return <Ag apt={a0} calc={(d: any, dir: string) => { const Q = n.replace(/\s/g, "").toUpperCase(); const f = Q && d.flights.find((x: any) => x.number.replace(/\s/g, "").toUpperCase() === Q);
  return <><div className="l2-form"><input placeholder="Flight number, e.g. LS1566" value={n} onChange={e => sn(e.target.value)} /></div>{!Q ? <Note>Type a flight on this board.</Note> : !f ? <Note>{Q} isn't on this board today.</Note> : !f.pred ? <Note>No forecast for {Q} (needs a scheduled feed).</Note> : <><V t={tone(f.pred.d)} b={`${Q}: ${m1(f.pred.d)} · ${f.pred.on}% on-time chance`} s={`confidence ${f.pred.c}`} />{(f.pred.factors || []).map((x: any, i: number) => <div key={i} className="lab-row"><span>{x.icon}</span><span className="grow">{x.label || x.kind}</span><b>{x.impact > 0 ? "+" : ""}{x.impact ?? ""}</b></div>)}<Row f={f} dir={dir} tz={d.tz} /></>}<Note>Statistical forecast with the factors behind it. Not a language model.</Note></>; }} />; }

// ======================= tools =======================
function Wx({ apt: a0, show }: any) { const [apt, set] = useApt(a0); const [w, sw] = useState<any>(undefined); useEffect(() => { sw(undefined); api(`/wx/${apt}`).then(sw).catch(() => sw(null)); }, [apt]); const m = w?.metar?.[0]; return <><AirportPicker v={apt} set={set} />{w === undefined ? <Note>Loading METAR…</Note> : !m ? <Note>No METAR for {apt}.</Note> : show(m)}</>; }
function Conv() { const [v, sv] = useState("100"); const x = +v || 0; const R: [string, string][] = [["knots → km/h", (x * 1.852).toFixed(1)], ["knots → mph", (x * 1.151).toFixed(1)], ["feet → metres", (x * .3048).toFixed(1)], ["metres → feet", (x * 3.281).toFixed(0)], ["nautical mi → km", (x * 1.852).toFixed(1)], ["km → miles", (x * .6214).toFixed(1)], ["hPa → inHg", (x * .02953).toFixed(2)], ["inHg → hPa", (x * 33.864).toFixed(0)], ["°C → °F", (x * 9 / 5 + 32).toFixed(1)], ["kg → lb", (x * 2.2046).toFixed(1)], ["litres jet fuel → kg (≈0.8)", (x * .8).toFixed(0)]];
  return <><div className="l2-form"><input inputMode="decimal" value={v} onChange={e => sv(e.target.value)} /></div>{R.map(([k, r]) => <div key={k} className="lab-row"><span className="grow">{k}</span><b>{r}</b></div>)}</>; }
function Two({ calc }: any) { const [a, sa] = useState("MAN"), [b, sb] = useState("JFK"); const A = useInfo(a), B = useInfo(b); return <><AirportPicker v={a} set={sa} /><AirportPicker v={b} set={sb} />{A?.lat && B?.lat ? calc(A, B) : <Note>Pick two airports.</Note>}</>; }
function Layover() { const [a, sa] = useState("10:20"), [b, sb] = useState("12:05"); const t = (s: string) => { const [h, m] = s.split(":").map(Number); return h * 60 + m; }; let m = t(b) - t(a); if (m < 0) m += 1440; return <><div className="l2-form"><input type="time" value={a} onChange={e => sa(e.target.value)} /><input type="time" value={b} onChange={e => sb(e.target.value)} /></div><V t={m < 45 ? "bad" : m < 75 ? "warn" : "good"} b={`${Math.floor(m / 60)}h ${m % 60}m`} s={m < 45 ? "Very tight for most hubs" : m < 75 ? "Tight — fine airside, risky with security again" : "Comfortable"} /><Note>Same time zone (both times at the connecting airport). Rule-of-thumb guidance only.</Note></>; }
function CopyBoard({ apt }: any) { const [ok, so] = useState(""); return <Ag apt={apt} calc={(d: any, dir: string) => { const txt = d.flights.slice(0, 60).map((f: any) => `${hm(S(f, dir).scheduled, d.tz)} ${f.number} ${oth(f, dir)?.iata || ""} ${f.statusText || f.status || ""}`).join("\n"); return <><button className="primary" onClick={() => navigator.clipboard?.writeText(txt).then(() => so("Copied ✓")).catch(() => so("Copy blocked by the browser"))}>Copy {Math.min(60, d.flights.length)} flights as text</button>{ok && <Note>{ok}</Note>}<pre className="sm muted mt8" style={{ whiteSpace: "pre-wrap", maxHeight: 260, overflow: "auto" }}>{txt}</pre></>; }} />; }
function RandDest({ apt, open }: any) { const [k, sk] = useState(0); return <Ag apt={apt} dir="dep" fixed calc={(d: any, _dir: string, now: number) => { const U = d.flights.filter((f: any) => up(f, "dep", now)); if (!U.length) return <Note>No departures left today.</Note>; const f = U[(k * 7919 + now % 9973) % U.length];
  return <><V t="good" b={`${oth(f, "dep")?.city || oth(f, "dep")?.iata}`} s={`${f.number} at ${hm(tT(f, "dep"), d.tz)}`} /><Row f={f} dir="dep" tz={d.tz} open={open} /><button className="secondary mt8" onClick={() => sk(k + 1)}>Spin again</button></>; }} />; }
function Gaps({ apt }: any) { return <Ag apt={apt} calc={(d: any, dir: string) => { const t = d.flights.filter((f: any) => !isCx(f)).map((f: any) => ms(tT(f, dir))).filter(isFinite).sort((a: number, b: number) => a - b); let g = [0, 0]; for (let i = 1; i < t.length; i++) if (t[i] - t[i - 1] > g[1] - g[0]) g = [t[i - 1], t[i]];
  return t.length < 2 ? <Note>Need 2+ flights.</Note> : <V t="good" b={`${Math.round((g[1] - g[0]) / 6e4)} min with no ${dir === "dep" ? "departures" : "arrivals"}`} s={`${hm(new Date(g[0]).toISOString(), d.tz)} → ${hm(new Date(g[1]).toISOString(), d.tz)}`} />; }} />; }
function Slot15({ apt }: any) { return <Ag apt={apt} calc={(d: any, dir: string) => { const M = grp(d.flights.filter((f: any) => !isCx(f)), f => { const t = ms(tT(f, dir)); return isFinite(t) ? String(Math.floor(t / 9e5) * 9e5) : ""; }); const R = Object.entries(M).sort((a, b) => b[1].length - a[1].length).slice(0, 8);
  return <Rk R={R.map(([k, fs]) => [hm(new Date(+k).toISOString(), d.tz) + "–" + hm(new Date(+k + 9e5).toISOString(), d.tz), fs.length])} />; }} />; }
function Rate({ apt }: any) { return <Ag apt={apt} calc={(d: any, dir: string, now: number) => { const n = d.flights.filter((f: any) => { const a = ms(S(f, dir).actual); return a > now - 36e5 && a <= now; }).length; const nx = d.flights.filter((f: any) => up(f, dir, now) && ms(tT(f, dir)) < now + 36e5).length; return <div className="lab-stats"><Stat l="Last 60 min" v={n} /><Stat l="Next 60 min" v={nx} /><Stat l="Per minute now" v={(n / 60).toFixed(2)} /></div>; }} />; }
function Totals({ apt }: any) { return <Ag apt={apt} calc={(d: any, dir: string) => { const k = d.flights.filter((f: any) => !isCx(f)).map((f: any) => km(f, dir, d)).filter(isFinite); const t = k.reduce((a: number, b: number) => a + b, 0);
  return <><div className="lab-stats"><Stat l="Total km" v={Math.round(t).toLocaleString()} /><Stat l="Mean" v={kmF(mean(k))} /><Stat l="Median" v={kmF(median(k))} /></div><div className="lab-stats"><Stat l="CO₂ (est.)" v={Math.round(t * 150 * .09 / 1000).toLocaleString() + " t"} /><Stat l="Around Earth" v={(t / 40075).toFixed(1) + "×"} /></div><Note>Great-circle distances. CO₂ assumes ~150 passengers × 90 g per passenger-km — a rough estimate.</Note></>; }} />; }
function Status3({ apt }: any) { return <Ag apt={apt} calc={(d: any, dir: string, now: number) => { const F = d.flights; const done = F.filter((f: any) => S(f, dir).actual || /landed|arrived|departed/i.test(f.status || "")).length, cx = F.filter(isCx).length; return <><div className="lab-stats"><Stat l="Done" v={done} tone="good" /><Stat l="To go" v={F.filter((f: any) => up(f, dir, now)).length} /><Stat l="Cancelled" v={cx} tone={cx ? "bad" : ""} /></div><Bar v={done} max={F.length} /><Note>{pct(done, F.length)}% of today's board is done.</Note></>; }} />; }
function Returns({ apt, miss }: any) { const [apt2, set] = useApt(apt); const s = useAB(apt2, "dep"), a = useAB(apt2, "arr"); return <Shell apt={apt2} set={set}><G b={s.b}>{d => <G b={a.b}>{r => { const D = grp(d.flights, f => oth(f, "dep")?.iata), A = grp(r.flights, f => oth(f, "arr")?.iata); const ks = Object.keys(D).filter(k => miss ? !A[k] : A[k]).sort((x, y) => D[y].length - D[x].length);
  return <>{ks.slice(0, 25).map(k => <div key={k} className="lab-row"><span className="grow">{D[k][0].destination?.city || k}<small className="faint"> {k}</small></span><b>{D[k].length} out{A[k] ? ` · ${A[k].length} in` : ""}</b></div>)}{!ks.length && <Note>None.</Note>}<Note>{miss ? "Places with departures today but no arrivals back — the return is probably tomorrow (overnight rotation)." : "Places with flights both ways today."}</Note></>; }}</G>}</G></Shell>; }
function Codes({ apt, kind }: any) { return <Ag apt={apt} calc={(d: any, dir: string) => { const M: Record<string, any> = {}; d.flights.forEach((f: any) => { if (kind === "al") { const k = alName(f); (M[k] ||= { k, c: f.airline?.iata || f.number?.slice(0, 2), x: f.airline?.country || "", n: 0 }).n++; } else { const p = oth(f, dir); if (p?.iata) (M[p.iata] ||= { k: p.city || p.iata, c: p.iata, x: p.country || "", n: 0 }).n++; } });
  return <>{Object.values(M).sort((a: any, b: any) => a.k.localeCompare(b.k)).map((x: any) => <div key={x.c + x.k} className="lab-row"><b className="mono">{x.c}</b><span className="grow">{x.k}<small className="faint"> {x.x}</small></span><small>{x.n}</small></div>)}</>; }} />; }
function TermGuide({ apt }: any) { return <Ag apt={apt} calc={(d: any, dir: string) => { const M: Record<string, Set<string>> = {}; d.flights.forEach((f: any) => { const t = S(f, dir).terminal; if (t) (M["T" + String(t).replace(/^T/i, "")] ||= new Set()).add(alName(f)); }); const ks = Object.keys(M).sort();
  return ks.length ? <>{ks.map(k => <div key={k} className="card m0 mt8"><b>{k}</b><div className="faint sm">{[...M[k]].sort().join(" · ")}</div></div>)}<Note>From today's board; airlines can move terminals.</Note></> : <Note>This board doesn't publish terminals.</Note>; }} />; }
function GateMap({ apt }: any) { return <Ag apt={apt} dir="dep" fixed calc={(d: any) => { const M: Record<string, Set<string>> = {}; d.flights.forEach((f: any) => { if (f.dep?.gate) (M[f.dep?.terminal ? "T" + String(f.dep.terminal).replace(/^T/i, "") : "Gates"] ||= new Set()).add(String(f.dep.gate)); }); const ks = Object.keys(M).sort();
  return ks.length ? <>{ks.map(k => <div key={k} className="card m0 mt8"><b>{k}</b><div className="l2-chips">{[...M[k]].sort((a, b) => a.localeCompare(b, undefined, { numeric: true })).map(g => <span key={g} className="chip">{g}</span>)}</div></div>)}</> : <Note>No gates published yet.</Note>; }} />; }
function DestWx({ apt: a0 }: any) { const s = useAB(a0, "dep"); const [W, sW] = useState<Record<string, any>>({}); return <Shell {...s}><G b={s.b}>{d => { const top = Object.entries(grp(d.flights, f => oth(f, s.dir)?.iata)).sort((a, b) => b[1].length - a[1].length).slice(0, 6).map(e => e[0]); return <DW top={top} W={W} sW={sW} />; }}</G></Shell>; }
function DW({ top, W, sW }: any) { useEffect(() => { top.forEach((k: string) => { if (!(k in W)) api(`/wx/${k}`).then(r => sW((w: any) => ({ ...w, [k]: r?.metar?.[0] || null }))).catch(() => sW((w: any) => ({ ...w, [k]: null }))); }); }, [top.join()]);
  return <>{top.map((k: string) => { const m = W[k]; return <div key={k} className="lab-row"><b className="mono">{k}</b><span className="grow">{m === undefined ? "loading…" : !m ? "no METAR" : `${m.temp}°C · wind ${m.wspd} kt${m.wgst ? " G" + m.wgst : ""}${m.wxString ? " · " + m.wxString : ""}`}</span><b className={m?.fltCat === "VFR" ? "good-t" : m ? "warn-t" : "faint"}>{m?.fltCat || "—"}</b></div>; })}<Note>Live METAR at today's 6 busiest destinations.</Note></>; }
function FltNo() { const [v, sv] = useState("BA117"); const m = v.toUpperCase().replace(/\s/g, "").match(/^([A-Z0-9]{2}[A-Z]?)(\d{1,4})([A-Z]?)$/); const [r, sr] = useState<any>(null); useEffect(() => { sr(null); if (m) api(`/airline/${m[1]}`).then(sr).catch(() => sr(null)); }, [m?.[1]]);
  return <><div className="l2-form"><input value={v} onChange={e => sv(e.target.value)} /></div>{!m ? <Note>Format: 2–3 letter/number airline code + 1–4 digits.</Note> : <><div className="lab-row"><span className="grow">Airline code</span><b>{m[1]} ({m[1].length === 3 ? "ICAO" : "IATA"})</b></div><div className="lab-row"><span className="grow">Flight</span><b>{m[2]}{m[3]}</b></div>{r?.name && <div className="lab-row"><span className="grow">Airline</span><b>{r.name}</b></div>}<div className="lab-row"><span className="grow">Hint</span><b>{+m[2] >= 9000 ? "ferry/charter range" : +m[2] >= 1000 ? "regional / short-haul style" : "mainline"}</b></div><Note>The hint is a loose industry convention, not a rule.</Note></>}</>; }
function SunTimes({ apt: a0 }: any) { const [apt, set] = useApt(a0); const i = useInfo(apt); const sun = (lat: number, lon: number, rise: boolean) => { const d = new Date(), N = Math.floor((+d - +new Date(d.getFullYear(), 0, 0)) / 864e5), r = Math.PI / 180; const g = 2 * Math.PI / 365 * (N - 1); const eq = 229.18 * (.000075 + .001868 * Math.cos(g) - .032077 * Math.sin(g) - .014615 * Math.cos(2 * g) - .040849 * Math.sin(2 * g)); const de = .006918 - .399912 * Math.cos(g) + .070257 * Math.sin(g) - .006758 * Math.cos(2 * g) + .000907 * Math.sin(2 * g); const c = (Math.cos(90.833 * r) / (Math.cos(lat * r) * Math.cos(de)) - Math.tan(lat * r) * Math.tan(de)); if (Math.abs(c) > 1) return null; const ha = Math.acos(c) / r; const m = 720 - 4 * (lon + (rise ? ha : -ha)) - eq; const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) + m * 6e4); return t.toISOString(); };
  return <><AirportPicker v={apt} set={set} />{i?.lat ? <div className="lab-stats"><Stat l="Sunrise" v={hm(sun(i.lat, i.lon, true) || undefined, i.tz)} /><Stat l="Sunset" v={hm(sun(i.lat, i.lon, false) || undefined, i.tz)} /><Stat l="Local time" v={new Date().toLocaleTimeString("en-GB", { timeZone: i.tz, hour: "2-digit", minute: "2-digit" })} /></div> : <Note>Loading airport…</Note>}<Note>NOAA approximation, ±2 min, local airport time.</Note></>; }

const CAT = "Live board", NET = "Network & routes", DIS = "Disruption", WX = "Weather", UT = "Calculators", AI = "Smart insights";
const ST = "Statistical", RB = "Rule-based";
const L = (id: string, n: string, d: string, c: string, ic: string, filt: any, o: any = {}) => T(id, n, d, c, ic, p => <FL {...p} filt={filt} sort={o.sort || byT} {...o} />);
const Gp = (id: string, n: string, d: string, c: string, ic: string, by: any, o: any = {}) => T(id, n, d, c, ic, p => <GR {...p} by={by} {...o} />);
const dW = (a: number, b: number) => (f: any, dir: string, _n: number, d: any) => inH(f, dir, d, a, b);
const kmW = (a: number, b: number) => (f: any, dir: string, _n: number, d: any) => { const k = km(f, dir, d); return k >= a && k < b; };
const bW = (a: number, b: number) => (f: any, dir: string, _n: number, d: any) => { const o = oth(f, dir); if (!o?.lat || !d.airport?.lat) return false; const x = brg(d.airport, o); return x >= a && x < b; };
const dlW = (a: number, b: number) => (f: any, dir: string) => { const x = dl(f, dir); return x != null && x >= a && x < b; };
const kmSub = (f: any, dir: string, d: any) => `${hm(tT(f, dir), d.tz)} · ${Math.round(km(f, dir, d)).toLocaleString()} km`;
const MX = (fs: any[], dir: string) => Math.max(...fs.map(f => dl(f, dir) ?? -999));
const Wrow = (rows: [string, string][]) => <>{rows.map(([k, v]) => <div key={k} className="lab-row"><span className="grow">{k}</span><b>{v}</b></div>)}</>;

